import{_ as i,o as t,c as r,a2 as o}from"./chunks/framework.DaAAbehN.js";const d=JSON.parse('{"title":"Pre-course Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"en/appendix/prep-checklist.md","filePath":"en/appendix/prep-checklist.md"}'),a={name:"en/appendix/prep-checklist.md"};function l(n,e,s,c,u,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="pre-course-checklist" tabindex="-1">Pre-course Checklist <a class="header-anchor" href="#pre-course-checklist" aria-label="Permalink to &quot;Pre-course Checklist&quot;">​</a></h1><blockquote><p>📌 Before you start learning, please make sure you have prepared the following items.</p></blockquote><hr><h2 id="i-account-preparation" tabindex="-1">I. Account Preparation <a class="header-anchor" href="#i-account-preparation" aria-label="Permalink to &quot;I. Account Preparation&quot;">​</a></h2><ul><li><p>[ ] <strong>ChatGPT Account</strong></p><ul><li>Registration URL: <a href="https://chatgpt.com" target="_blank" rel="noreferrer">https://chatgpt.com</a></li><li>Recommended version: Plus ($20/month) or Pro ($200/month)</li><li>Free version works too, but has limited quota</li></ul></li><li><p>[ ] <strong>Email Verification</strong></p><ul><li>Make sure your registered email has been verified</li><li>Check your spam folder to confirm the verification email was received</li></ul></li></ul><hr><h2 id="ii-device-preparation" tabindex="-1">II. Device Preparation <a class="header-anchor" href="#ii-device-preparation" aria-label="Permalink to &quot;II. Device Preparation&quot;">​</a></h2><ul><li><p>[ ] <strong>Computer Operating System</strong></p><ul><li>macOS users: macOS 12.0 or later</li><li>Windows users: Windows 10 or later</li><li>Chromebook users: Chrome OS supported</li></ul></li><li><p>[ ] <strong>Browser</strong></p><ul><li>Recommended: Latest version of Chrome, Edge, or Firefox</li><li>Make sure your browser is updated to the latest version</li></ul></li><li><p>[ ] <strong>Storage Space</strong></p><ul><li>Reserve at least 500MB for installation and cache</li></ul></li></ul><hr><h2 id="iii-network-environment" tabindex="-1">III. Network Environment <a class="header-anchor" href="#iii-network-environment" aria-label="Permalink to &quot;III. Network Environment&quot;">​</a></h2><ul><li>[ ] <strong>Stable Internet Connection</strong><ul><li>Recommended broadband speed: 50Mbps or higher</li><li>If using WiFi, ensure good signal strength</li><li>Avoid using on public WiFi (may affect connection stability)</li></ul></li></ul><hr><h2 id="iv-practice-materials" tabindex="-1">IV. Practice Materials <a class="header-anchor" href="#iv-practice-materials" aria-label="Permalink to &quot;IV. Practice Materials&quot;">​</a></h2><ul><li><p>[ ] <strong>A Folder to Organize</strong></p><ul><li>Create a folder named &quot;Codex Practice&quot; on your desktop</li><li>Put some different types of files in it for practice: <ul><li>2-3 text files (.txt)</li><li>2-3 image files (.jpg or .png)</li><li>1-2 PDF files</li><li>1 Excel file (.xlsx)</li></ul></li></ul></li><li><p>[ ] <strong>A Notebook</strong></p><ul><li>Record questions and solutions you encounter during learning</li><li>Record useful prompt templates you discover</li></ul></li></ul><hr><h2 id="v-mindset-preparation" tabindex="-1">V. Mindset Preparation <a class="header-anchor" href="#v-mindset-preparation" aria-label="Permalink to &quot;V. Mindset Preparation&quot;">​</a></h2><ul><li>[ ] <strong>Stay Curious</strong> — Try different prompts and see what Codex can do</li><li>[ ] <strong>Don&#39;t Fear Mistakes</strong> — Making mistakes is part of learning; learning to fix is more important than not making mistakes</li><li>[ ] <strong>Take It Step by Step</strong> — Don&#39;t rush through each module; practice hands-on</li></ul><hr><h2 id="vi-security-check" tabindex="-1">VI. Security Check <a class="header-anchor" href="#vi-security-check" aria-label="Permalink to &quot;VI. Security Check&quot;">​</a></h2><ul><li>[ ] <strong>Back Up Important Files</strong> — Backup before letting Codex operate on important files</li><li>[ ] <strong>Set Appropriate Permissions</strong> — Beginners should use &quot;Default Permission&quot; mode</li><li>[ ] <strong>Don&#39;t Enter Sensitive Information</strong> — Passwords, bank card numbers, etc. should never be entered to AI</li></ul><hr><h2 id="vii-all-set" tabindex="-1">VII. All Set! <a class="header-anchor" href="#vii-all-set" aria-label="Permalink to &quot;VII. All Set!&quot;">​</a></h2><p>Once you&#39;ve checked all the items above, you&#39;re ready to start Lesson 1!</p><p>👉 <a href="/CodexCourse/en/modules/module-1/lesson-1.html">Lesson 1: What is an AI Programming Assistant?</a></p>',24)])])}const m=i(a,[["render",l]]);export{d as __pageData,m as default};
